"""Probabilités et statistiques : lois, estimation, tests, régression, bootstrap, simulation."""
from __future__ import annotations

from patrick.knowledge.dictionary import d

T = "probas"
TERMS = [
    d(T, "variable_aleatoire", "Variable aléatoire", "Random variable", 1,
      "Grandeur dont la valeur dépend du hasard : le rendement de demain, le cours dans un an. On la décrit par sa loi (les valeurs possibles et leurs probabilités), dont l'espérance et la variance résument le centre et la dispersion.",
      "A quantity whose value depends on chance: tomorrow's return, the price in a year. It is described by its distribution (possible values and their probabilities), whose mean and variance summarise centre and spread.",
      see="esperance variance"),
    d(T, "esperance", "Espérance (moyenne théorique)", "Expectation (theoretical mean)", 1,
      "Moyenne des valeurs possibles d'une variable aléatoire pondérées par leurs probabilités : ce qu'on obtiendrait « en moyenne » en répétant l'expérience un grand nombre de fois. Elle est linéaire : E[aX + bY] = aE[X] + bE[Y].",
      "Average of a random variable's possible values weighted by their probabilities: what one would get 'on average' repeating the experiment many times. It is linear: E[aX + bY] = aE[X] + bE[Y].",
      formula=r"E[X] = \sum_i x_i\,p_i", see="variable_aleatoire loi_grands_nombres"),
    d(T, "loi_normale", "Loi normale (gaussienne)", "Normal (Gaussian) distribution", 1,
      "Loi en cloche entièrement décrite par sa moyenne μ et son écart-type σ ; 68 % des valeurs à ±1σ, 95 % à ±1,96σ, 99,7 % à ±3σ. Commode mais trop optimiste pour les rendements financiers, dont les queues sont plus épaisses.",
      "Bell-shaped law fully described by its mean μ and standard deviation σ; 68% of values within ±1σ, 95% within ±1.96σ, 99.7% within ±3σ. Convenient but too optimistic for financial returns, whose tails are fatter.",
      formula=r"f(x) = \frac{1}{\sigma\sqrt{2\pi}}\,e^{-\frac{(x-\mu)^2}{2\sigma^2}}", see="queues_epaisses theoreme_central_limite", alias="gaussienne"),
    d(T, "loi_lognormale", "Loi log-normale", "Log-normal distribution", 2,
      "Loi d'une variable dont le logarithme est normal : toujours positive et asymétrique à droite. Elle modélise les prix quand les log-rendements sont gaussiens, car un prix ne peut être négatif.",
      "Law of a variable whose logarithm is normal: always positive and right-skewed. It models prices when log returns are Gaussian, since a price cannot be negative.",
      see="loi_normale log_rendement"),
    d(T, "loi_student", "Loi de Student", "Student's t distribution", 2,
      "Loi symétrique en cloche aux queues plus épaisses que la normale, réglées par un nombre de degrés de liberté ν (plus ν est petit, plus les queues sont épaisses ; ν → ∞ redonne la normale). Elle modélise bien les rendements journaliers (ν de 4 à 8).",
      "Symmetric bell-shaped law with fatter tails than the normal, set by degrees of freedom ν (the smaller ν, the fatter the tails; ν → ∞ gives the normal). It models daily returns well (ν of 4 to 8).",
      see="queues_epaisses loi_normale"),
    d(T, "loi_pareto_valeurs_extremes", "Loi de Pareto et valeurs extrêmes", "Pareto law and extreme values", 3,
      "Les queues de nombreuses lois financières décroissent comme une puissance (loi de Pareto) plutôt que comme une exponentielle. La théorie des valeurs extrêmes (loi de Pareto généralisée) modélise directement les dépassements de seuil, utile pour la VaR à 99,9 %.",
      "Tails of many financial laws decay like a power (Pareto law) rather than an exponential. Extreme-value theory (generalised Pareto) models threshold exceedances directly, useful for 99.9% VaR.",
      see="queues_epaisses var_methodes", alias="EVT; GPD"),
    d(T, "quantile_mediane", "Quantile, médiane, percentile", "Quantile, median, percentile", 1,
      "Le quantile à p % est la valeur sous laquelle se trouvent p % des observations ; la médiane est le quantile à 50 %. La médiane est robuste aux valeurs extrêmes, contrairement à la moyenne.",
      "The p% quantile is the value below which p% of observations lie; the median is the 50% quantile. The median is robust to extreme values, unlike the mean.",
      see="valeur_aberrante var_methodes"),
    d(T, "loi_grands_nombres", "Loi des grands nombres", "Law of large numbers", 1,
      "La moyenne d'un échantillon se rapproche de l'espérance quand le nombre d'observations croît. C'est la raison pour laquelle plus de données donne des estimations plus fiables, à condition qu'elles soient indépendantes et représentatives.",
      "A sample's mean approaches the expectation as the number of observations grows. It is why more data gives more reliable estimates, provided they are independent and representative.",
      see="esperance theoreme_central_limite"),
    d(T, "theoreme_central_limite", "Théorème central limite", "Central limit theorem", 2,
      "La moyenne d'un grand nombre d'observations indépendantes est approximativement normale, quelle que soit la loi d'origine (variance finie). Il justifie les intervalles de confiance et les tests usuels, mais converge lentement quand les queues sont épaisses.",
      "The mean of many independent observations is approximately normal whatever the original law (finite variance). It justifies confidence intervals and the usual tests, but converges slowly when tails are fat.",
      formula=r"\sqrt{n}\,\frac{\bar X - \mu}{\sigma} \xrightarrow{d} \mathcal N(0,1)", see="loi_normale intervalle_de_confiance"),
    d(T, "estimateur_biais", "Estimateur, biais et variance d'un estimateur", "Estimator, bias and estimator variance", 2,
      "Un estimateur est une règle de calcul à partir des données (la moyenne empirique estime l'espérance). Il est sans biais si, en moyenne, il vise juste ; son erreur dépend aussi de sa variance. Un peu de biais peut valoir de la variance en moins (régularisation).",
      "An estimator is a computation rule from data (the sample mean estimates the expectation). It is unbiased if on average it hits the target; its error also depends on its variance. A little bias can be worth less variance (regularisation).",
      see="biais_variance maximum_vraisemblance"),
    d(T, "maximum_vraisemblance", "Maximum de vraisemblance", "Maximum likelihood", 3,
      "Méthode d'estimation qui choisit les paramètres rendant les données observées les plus probables : on maximise la vraisemblance L(θ) = produit des densités. C'est le moteur de l'estimation des GARCH, ARMA et Markov-switching.",
      "Estimation method choosing the parameters that make the observed data most probable: one maximises the likelihood L(θ) = product of densities. It drives estimation of GARCH, ARMA and Markov-switching.",
      formula=r"\hat\theta = \arg\max_\theta \sum_t \ln f(x_t;\theta)", see="garch_notion information_criteria", alias="MLE; vraisemblance"),
    d(T, "intervalle_de_confiance", "Intervalle de confiance", "Confidence interval", 2,
      "Plage de valeurs qui contient le vrai paramètre dans, par exemple, 95 % des échantillons possibles. Un intervalle étroit signale une estimation précise ; il se resserre en 1/√n quand on ajoute des données.",
      "Range of values containing the true parameter in, say, 95% of possible samples. A narrow interval signals a precise estimate; it tightens as 1/√n when data are added.",
      formula=r"\bar x \pm 1{,}96\,\frac{s}{\sqrt n}", see="erreur_type theoreme_central_limite"),
    d(T, "erreur_type", "Erreur-type", "Standard error", 2,
      "Écart-type d'un estimateur (et non des données) : il mesure l'incertitude de l'estimation. L'estimateur divisé par son erreur-type donne la statistique t ; une valeur supérieure à 2 en valeur absolue est « significative » à 5 %.",
      "Standard deviation of an estimator (not of the data): it measures the estimation uncertainty. The estimator divided by its standard error gives the t-statistic; an absolute value above 2 is 'significant' at 5%.",
      see="statistique_t intervalle_de_confiance"),
    d(T, "test_hypothese", "Test d'hypothèse", "Hypothesis test", 2,
      "Procédure qui confronte une hypothèse nulle H0 (« pas d'effet ») aux données. On calcule une statistique et sa p-value ; si elle est sous le seuil (5 %), on rejette H0. Ne pas rejeter ne prouve pas H0 : peut-être manque-t-on de puissance.",
      "Procedure confronting a null hypothesis H0 ('no effect') with data. A statistic and its p-value are computed; if below the threshold (5%), H0 is rejected. Failing to reject does not prove H0: perhaps power is lacking.",
      see="p_value erreur_type1_type2"),
    d(T, "erreur_type1_type2", "Erreurs de type I et II, puissance", "Type I and II errors, power", 2,
      "L'erreur de type I est de rejeter H0 à tort (fausse découverte, probabilité = niveau du test) ; celle de type II est de ne pas rejeter H0 à tort. La puissance, 1 − P(type II), est la chance de détecter un vrai effet : elle croît avec l'effet et le nombre de données.",
      "Type I error is wrongly rejecting H0 (false discovery, probability = test level); type II is wrongly failing to reject. Power, 1 − P(type II), is the chance of detecting a real effect: it grows with effect size and sample size.",
      see="test_hypothese bh_fdr"),
    d(T, "statistique_t", "Statistique t et test de Student", "t-statistic and Student test", 2,
      "Rapport d'un estimateur à son erreur-type. Sous H0 il suit à peu près une loi de Student ; |t| > 2 environ rejette « effet nul » à 5 %. Les p-values issues de séries autocorrélées exigent des erreurs-types corrigées (Newey-West).",
      "Ratio of an estimator to its standard error. Under H0 it roughly follows a Student law; |t| > 2 or so rejects 'zero effect' at 5%. P-values from autocorrelated series require corrected standard errors (Newey–West).",
      formula=r"t = \frac{\hat\beta}{\operatorname{se}(\hat\beta)}", see="erreur_type hac_newey_west"),
    d(T, "chi_deux", "Test du chi-deux", "Chi-squared test", 3,
      "Loi de la somme de carrés de normales, utilisée pour tester des ensembles de contraintes (rapport de vraisemblance, Ljung-Box, Kupiec). Le nombre de degrés de liberté est le nombre de contraintes testées.",
      "Law of a sum of squared normals, used to test sets of restrictions (likelihood ratio, Ljung–Box, Kupiec). Degrees of freedom equal the number of restrictions tested.",
      see="test_hypothese ljung_box"),
    d(T, "bootstrap", "Bootstrap", "Bootstrap", 3,
      "Estimer l'incertitude d'une statistique en retirant au hasard, avec remise, des observations de l'échantillon pour créer de nombreux échantillons fictifs. Utile quand on ne connaît pas la loi de la statistique.",
      "Estimating a statistic's uncertainty by randomly redrawing observations with replacement from the sample to create many fictitious samples. Useful when the statistic's distribution is unknown.",
      see="bootstrap_blocs intervalle_de_confiance"),
    d(T, "bootstrap_blocs", "Bootstrap par blocs", "Block bootstrap", 3,
      "Variante qui retire des blocs consécutifs d'observations plutôt que des points isolés, pour préserver l'autocorrélation d'une série temporelle. Indispensable pour les rendements, dont les voisins ne sont pas indépendants.",
      "Variant redrawing consecutive blocks of observations rather than isolated points, to preserve a time series' autocorrelation. Essential for returns, whose neighbours are not independent.",
      see="bootstrap model_confidence_set"),
    d(T, "monte_carlo", "Simulation de Monte-Carlo", "Monte Carlo simulation", 2,
      "Estimer une quantité (un prix d'option, une VaR) en simulant un grand nombre de scénarios aléatoires selon un modèle puis en moyennant les résultats. Précise en 1/√n : 100 fois plus de tirages pour 10 fois plus de précision.",
      "Estimating a quantity (an option price, a VaR) by simulating a large number of random scenarios from a model then averaging results. Accuracy goes as 1/√n: 100 times more draws for 10 times more precision.",
      see="var_methodes bootstrap"),
    d(T, "regression_mco", "Régression linéaire (moindres carrés ordinaires)", "Linear regression (OLS)", 2,
      "Modèle y = a + b x + erreur où l'on choisit a et b qui minimisent la somme des carrés des erreurs. Le coefficient b mesure l'effet moyen de x sur y ; le bêta d'un titre est le b de sa régression sur le marché.",
      "Model y = a + b x + error with a and b chosen to minimise the sum of squared errors. The coefficient b measures the mean effect of x on y; a stock's beta is the b of its regression on the market.",
      formula=r"\hat\beta = (X^\top X)^{-1} X^\top y", see="r_carre beta"),
    d(T, "r_carre", "R² (coefficient de détermination)", "R-squared", 2,
      "Part de la variance de y expliquée par la régression, entre 0 et 1. Sur des rendements journaliers, un R² de 1 % est déjà notable ; un R² élevé sur des niveaux de prix est souvent trompeur (régression fallacieuse).",
      "Share of y's variance explained by the regression, between 0 and 1. On daily returns, an R² of 1% is already notable; a high R² on price levels is often misleading (spurious regression).",
      see="regression_mco regression_fallacieuse"),
    d(T, "multicolinearite", "Multicolinéarité", "Multicollinearity", 3,
      "Quand des variables explicatives sont très corrélées entre elles, leurs coefficients individuels deviennent instables et imprécis, même si la prévision d'ensemble reste bonne. Les régularisations (ridge, lasso) la contiennent.",
      "When explanatory variables are highly correlated with each other, their individual coefficients become unstable and imprecise, even if the overall forecast stays good. Regularisation (ridge, lasso) contains it.",
      see="regression_mco lasso"),
    d(T, "heteroscedasticite", "Hétéroscédasticité", "Heteroskedasticity", 2,
      "Variance des erreurs qui n'est pas constante : la volatilité des rendements change dans le temps. Elle invalide les erreurs-types usuelles de la régression et justifie les modèles GARCH et les erreurs-types robustes.",
      "Error variance that is not constant: return volatility changes over time. It invalidates the usual regression standard errors and justifies GARCH models and robust standard errors.",
      see="garch_notion hac_newey_west"),
    d(T, "autocorrelation_notion", "Autocorrélation (notion)", "Autocorrelation (concept)", 2,
      "Corrélation d'une série avec elle-même décalée dans le temps. Quasi nulle pour les rendements, forte pour la volatilité. Son existence rend inutilisables les tests qui supposent l'indépendance des observations.",
      "Correlation of a series with a lagged copy of itself. Near zero for returns, strong for volatility. Its presence invalidates tests that assume independent observations.",
      see="exp_acf ljung_box"),
    d(T, "hac_newey_west", "Erreurs-types robustes (HAC, Newey-West)", "Robust standard errors (HAC, Newey–West)", 3,
      "Estimation de l'erreur-type qui reste valable malgré l'hétéroscédasticité et l'autocorrélation des erreurs : on pondère les autocovariances par des poids décroissants (noyau de Bartlett). À utiliser par défaut pour des séries temporelles.",
      "Standard-error estimation that stays valid despite heteroskedasticity and error autocorrelation: autocovariances are weighted with declining weights (Bartlett kernel). Use by default for time series.",
      see="statistique_t heteroscedasticite", alias="HAC; Newey-West"),
    d(T, "regression_fallacieuse", "Régression fallacieuse", "Spurious regression", 3,
      "Deux marches aléatoires indépendantes régressées l'une sur l'autre montrent souvent un R² élevé et un t « significatif » (Granger et Newbold, 1974). Remède : travailler sur des séries stationnaires (rendements) ou tester la cointégration.",
      "Two independent random walks regressed on each other often show a high R² and a 'significant' t (Granger and Newbold, 1974). Remedy: work with stationary series (returns) or test cointegration.",
      see="exp_coint racine_unitaire"),
    d(T, "variable_omise_endogeneite", "Variable omise et endogénéité", "Omitted variable and endogeneity", 3,
      "Si une variable qui influence y et x est absente du modèle, le coefficient de x capte aussi son effet (biais). L'endogénéité, ou le fait que y influence aussi x, rend la lecture causale d'une régression fragile.",
      "If a variable influencing both y and x is missing from the model, x's coefficient also picks up its effect (bias). Endogeneity, or y also influencing x, makes a causal reading of a regression fragile.",
      see="regression_mco exp_granger"),
    d(T, "theoreme_bayes", "Théorème de Bayes", "Bayes' theorem", 2,
      "Règle pour mettre à jour une probabilité à la lumière d'une information : P(A|B) = P(B|A) P(A) / P(B). Elle est à la base du raisonnement bayésien, du filtre de Kalman et du rétrécissement vers une moyenne a priori.",
      "Rule for updating a probability in light of information: P(A|B) = P(B|A) P(A) / P(B). It underlies Bayesian reasoning, the Kalman filter and shrinkage toward a prior mean.",
      formula=r"P(A\mid B) = \frac{P(B\mid A)\,P(A)}{P(B)}", see="kalman"),
    d(T, "a_priori_retrecissement", "A priori et rétrécissement (shrinkage)", "Prior and shrinkage", 3,
      "Tirer une estimation bruitée vers une valeur de référence plausible (la moyenne générale) : plus l'échantillon est petit, plus on se rapproche de la référence. Il réduit l'erreur totale à échantillon réduit ; c'est le principe de Ledoit-Wolf.",
      "Pulling a noisy estimate toward a plausible reference value (the grand mean): the smaller the sample, the closer to the reference. It reduces total error with small samples; it is the principle behind Ledoit–Wolf.",
      see="ledoit_wolf theoreme_bayes"),
    d(T, "entropie_kl", "Entropie et divergence de Kullback-Leibler", "Entropy and Kullback–Leibler divergence", 3,
      "L'entropie mesure l'incertitude d'une loi ; la divergence KL mesure à quel point une loi s'éloigne d'une autre. Elles fondent l'information mutuelle et plusieurs fonctions de perte en apprentissage (entropie croisée).",
      "Entropy measures a law's uncertainty; KL divergence measures how far one law departs from another. They underpin mutual information and several learning loss functions (cross-entropy).",
      formula=r"D_{KL}(P\|Q) = \sum_x P(x)\ln\frac{P(x)}{Q(x)}", see="exp_mi entropie_croisee"),
    d(T, "copule", "Copule", "Copula", 3,
      "Fonction qui sépare la structure de dépendance de plusieurs variables de leurs lois individuelles. Une copule gaussienne a une dépendance de queue nulle ; une copule de Student ou de Clayton capte la tendance à chuter ensemble en crise.",
      "Function separating the dependence structure of several variables from their individual laws. A Gaussian copula has zero tail dependence; a Student or Clayton copula captures the tendency to fall together in a crisis.",
      see="exp_tail correlation_de_crise"),
    d(T, "marche_aleatoire", "Marche aléatoire", "Random walk", 2,
      "Processus où chaque variation est imprévisible et indépendante des précédentes : x_t = x_{t−1} + ε_t. Les prix d'actifs efficients suivent à peu près une marche aléatoire : le meilleur prévision de demain est aujourd'hui.",
      "Process where each change is unpredictable and independent of past ones: x_t = x_{t−1} + ε_t. Efficient asset prices roughly follow a random walk: the best forecast of tomorrow is today.",
      formula=r"x_t = x_{t-1} + \varepsilon_t", see="racine_unitaire hypothese_efficience"),
    d(T, "hypothese_efficience", "Hypothèse d'efficience des marchés", "Efficient market hypothesis", 2,
      "Les prix reflètent toute l'information disponible, de sorte qu'aucune stratégie ne bat durablement le marché après risque et coûts. Sous sa forme faible, les prix passés ne prédisent pas les prix futurs. Débattue, mais bon point de départ sceptique.",
      "Prices reflect all available information, so no strategy durably beats the market after risk and costs. In its weak form, past prices do not predict future prices. Debated, but a good sceptical starting point.",
      see="marche_aleatoire alpha_jensen"),
    d(T, "martingale", "Martingale", "Martingale", 3,
      "Processus dont la meilleure prévision du futur, sachant le passé, est la valeur actuelle. Un prix actualisé sous probabilité risque-neutre est une martingale : c'est la base de la valorisation des dérivés.",
      "Process whose best forecast of the future, given the past, is the current value. A discounted price under risk-neutral probability is a martingale: the basis of derivative pricing.",
      see="marche_aleatoire black_scholes"),
    d(T, "loi_conditionnelle", "Espérance et variance conditionnelles", "Conditional expectation and variance", 3,
      "Moyenne ou variance d'une variable sachant l'information disponible jusqu'à la date précédente. Le rendement de demain a une moyenne conditionnelle quasi constante et une variance conditionnelle très variable : le sujet des modèles ARMA et GARCH.",
      "Mean or variance of a variable given the information available up to the previous date. Tomorrow's return has a nearly constant conditional mean and a very variable conditional variance: the subject of ARMA and GARCH models.",
      course="econometrie#la-question-posee-a-une-serie-de-rendements", see="garch_notion"),
    d(T, "sous_echantillon_puissance", "Taille d'échantillon et puissance", "Sample size and power", 2,
      "Détecter un petit effet exige beaucoup de données : l'erreur-type baisse en 1/√n. Pour un Sharpe annuel de 0,5, il faut plusieurs dizaines d'années pour qu'il soit statistiquement distinct de zéro.",
      "Detecting a small effect requires lots of data: the standard error falls as 1/√n. For an annual Sharpe of 0.5, several decades are needed for it to be statistically distinct from zero.",
      see="erreur_type1_type2 sharpe_probabiliste"),
    d(T, "correlation_pearson_rang", "Corrélation de Pearson, Spearman et Kendall", "Pearson, Spearman and Kendall correlation", 2,
      "Pearson mesure le lien linéaire et est sensible aux valeurs extrêmes ; Spearman et Kendall travaillent sur les rangs, donc mesurent tout lien monotone et résistent aux aberrations. Les trois peuvent différer beaucoup sur des rendements à queues épaisses.",
      "Pearson measures linear association and is sensitive to extremes; Spearman and Kendall work on ranks, so they measure any monotone link and resist outliers. The three can differ widely on fat-tailed returns.",
      see="correlation_notion spearman_holdout"),
]
